using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private readonly ActorDataOperations _data=new();private readonly ActorPropertyOperations _properties=new();private readonly ActorAnimationTrackOperations _tracks=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorRuntimeOperations _clips=new();private readonly ActorTransformationStateOperations _states=new();
    public void add_keyframe_button(Control owner,Control parent,Resource actor,Resource property,string[] path,Variant fallback)
    {
        if(!_properties.can_keyframe(property))return;var model=Ui<RefCounted>(owner,"model");string actorId=actor.Get("id").AsString(),propertyId=property.Get("id").AsString();var button=new Button{Name=propertyId+"_keyframe",CustomMinimumSize=new Vector2(28,0),ToggleMode=true};var style=new StyleBoxFlat{BgColor=new Color("296c5b"),BorderColor=new Color("94efca"),ContentMarginLeft=5,ContentMarginRight=5};style.SetBorderWidthAll(2);style.SetCornerRadiusAll(4);button.AddThemeStyleboxOverride("pressed",style);button.AddThemeStyleboxOverride("hover_pressed",style);parent.AddChild(button);var insert=new Button{Name=propertyId+"_insert_keyframe",Text="+◆",TooltipText="Insert a keyframe at the timeline playhead"};parent.AddChild(insert);double LocalTime(){var clip=_timeline.clip_for_actor_id(model,actorId);return clip!=null?_clips.local_time(clip,model.Get("playhead_time").AsDouble()):0;}
        void Update(){var track=_data.animation_track(actor,path);bool keyed=track!=null&&_tracks.key_at(track,LocalTime())!=null;button.Text=keyed?"◆":track!=null?"◈":"◇";bool active=model.Get("overlay_actor_id").AsString()==actorId&&model.Get("overlay_path").AsStringArray().SequenceEqual(path);button.Modulate=active?Colors.White:keyed?new Color("ffce80"):track!=null?new Color("72cfb8"):Colors.White;button.SetPressedNoSignal(active);button.TooltipText=$"Show / hide {property.Get("label").AsString()} keyframes on the actor. Only one property is shown at once. Right-click to remove keys.";}Update();owner.Get("_updaters").AsGodotArray().Add(Callable.From(Update));
        void Insert(){var basis=_animation.value_at_path(actor,path);if(basis.VariantType==Variant.Type.Nil)basis=fallback.VariantType!=Variant.Type.Nil?fallback:_properties.create_default(property);var value=_animation.sampled_value(actor,path,LocalTime(),basis);if(actor.Get("type_id").AsString()=="transform_image_2d"&&path.Length==2&&path[0]=="component_states"){var assets=ActorTransformationStates.Assets;var asset=_states.load_asset(assets,actor);var document=asset["document"].As<Resource>();var item=document?.Call("component",path[1]).As<Resource>();if(item!=null)value=_states.current(actor,item,LocalTime());}var options=property.Get("options").AsGodotDictionary();string label=(path.Length>1?string.Join(" / ",path.Take(path.Length-1)):options.GetValueOrDefault("group","Properties").AsString())+" / "+property.Get("label").AsString();label=options.GetValueOrDefault("track_label",label).AsString();_timeline.add_keyframe(model,actor,path,label,value,options.ContainsKey("choices"),false);var track=_data.animation_track(actor,path);var panel=owner.GetTree().GetFirstNodeInGroup("actor_keyframe_editors") as Control;if(panel!=null&&track!=null){var key=_tracks.key_at(track,LocalTime());if(key==null)return;var lanes=panel.Get("lanes").As<Control>();var selected=lanes.Get("selected_keys").AsGodotArray();selected.Clear();selected.Add(key.Get("id"));panel.Call("_build_details");lanes.QueueRedraw();}}
        insert.Pressed+=Insert;button.Pressed+=()=>{bool enabled=button.ButtonPressed;model.Set("overlay_actor_id",enabled?actorId:"");model.Set("overlay_path",enabled?(string[])path.Clone():Array.Empty<string>());if(enabled&&_data.animation_track(actor,path)==null)Insert();model.EmitSignal("changed");};var menu=new PopupMenu();button.AddChild(menu);menu.AddItem("Remove Key at Cursor",0);menu.AddItem("Remove Property Animation",1);button.GuiInput+=ev=>{if(ev is InputEventMouseButton mouse&&mouse.Pressed&&mouse.ButtonIndex==MouseButton.Right){var track=_data.animation_track(actor,path);menu.SetItemDisabled(0,track==null||_tracks.key_at(track,LocalTime())==null);menu.SetItemDisabled(1,track==null);menu.Position=new Vector2I((int)mouse.GlobalPosition.X,(int)mouse.GlobalPosition.Y);menu.Popup();owner.GetViewport().SetInputAsHandled();}};menu.IdPressed+=id=>{var track=_data.animation_track(actor,path);if(track==null)return;var ids=new GArray();foreach(var partValue in actor.Get("animation_tracks").AsGodotArray()){var part=partValue.As<Resource>();if(!part.Get("path").AsStringArray().SequenceEqual(path))continue;var current=_tracks.key_at(part,LocalTime());foreach(var keyValue in part.Get("keys").AsGodotArray()){var key=keyValue.As<Resource>();if(id==1||key==current)ids.Add(key.Get("id"));}}_timeline.delete_keyframes(model,actor,ids);};
    }
}
